{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "transform": [
    {
      "calculate": "['Fastest route', 'Weather-aware route'][datum.__input__]",
      "as": "scenario_name"
    }
  ],
  "encoding": {
    "x": {
      "field": "scenario_name",
      "type": "nominal",
      "title": null,
      "axis": {
        "labelAngle": 0
      },
      "sort": [
        "Fastest route",
        "Weather-aware route"
      ]
    },
    "y": {
      "field": "duration",
      "type": "quantitative",
      "title": "Duration (min)"
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "tooltip": true
      },
      "encoding": {
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "legend": null,
          "scale": {
            "domain": [
              "Fastest route",
              "Weather-aware route"
            ],
            "range": [
              "#4e79a7",
              "#f28e2c"
            ]
          }
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "dy": -6,
        "baseline": "bottom"
      },
      "encoding": {
        "text": {
          "field": "duration",
          "type": "quantitative",
          "format": ".2f"
        }
      }
    }
  ]
}

